<script setup lang="ts">
const db=useSupabaseClient(),loading=ref(true),error=ref(''),status=ref(''),school=ref(''),student=ref(''),events=ref<any[]>([]),busy=ref('')
async function load(){loading.value=true;const {data:{user}}=await db.auth.getUser();if(!user){await navigateTo('/login');return}const req=await db.from('student_account_requests').select('status,school_id,student_id').eq('user_id',user.id).maybeSingle();if(req.error){error.value=req.error.message;loading.value=false;return}status.value=req.data?.status||'';if(status.value!=='approved'){loading.value=false;return}const [s,st,e]=await Promise.all([db.from('schools').select('name').eq('id',req.data.school_id).single(),db.from('students').select('given_name,family_name').eq('id',req.data.student_id).single(),db.rpc('my_available_student_events')]);school.value=s.data?.name||'';student.value=st.data?`${st.data.given_name} ${st.data.family_name}`:'';events.value=e.data||[];error.value=e.error?.message||'';loading.value=false}
onMounted(load)
async function toggle(e:any){error.value='';busy.value=e.event_id;const r=await db.rpc(e.registered?'withdraw_my_student_event':'register_my_student_event',{p_event_id:e.event_id});busy.value='';if(r.error){error.value=r.error.message;return}await load()}
async function signOut(){await db.auth.signOut();await navigateTo('/login')}
</script>
<template><div class="page"><div class="shell admin-section"><header class="top"><NuxtLink to="/" class="brand"><img src="/logo.png" alt="School Sports Tracker"><div><strong>SCHOOL SPORTS TRACKER</strong><small>STUDENT PORTAL</small></div></NuxtLink><button class="secondary" @click="signOut">Sign Out</button></header><h1>My Sports Dashboard</h1><p v-if="loading">Loading…</p><p v-else-if="status!=='approved'" class="notice">{{status==='pending'?'Your account is awaiting school approval.':status==='rejected'?'Your school has declined your request.':'Your account is not yet linked to a student record.'}} <NuxtLink v-if="!status" to="/student/onboarding"><u>Request access</u></NuxtLink></p><template v-else><p class="notice">{{student}} · {{school}}</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="cards"><div class="card"><h2>Available Events</h2><p>{{events.filter(e=>!e.registered).length}} open for registration</p></div><div class="card"><h2>My Registrations</h2><p>{{events.filter(e=>e.registered).length}} registered events</p></div><div class="card"><h2>School</h2><p>{{school}}</p></div></div><div class="card"><h2>Events and Registrations</h2><p v-if="!events.length">No eligible individual events are currently open. Ask your school to publish events for registration.</p><div v-for="e in events" :key="e.event_id" class="data-row"><div><strong>{{e.event_name}}</strong><p>{{e.competition_name}} · {{e.starts_on||'Date TBA'}} <span v-if="e.age_group"> · {{e.age_group}}</span> <span v-if="e.division"> · {{e.division}}</span></p></div><button class="btn" :disabled="busy===e.event_id" @click="toggle(e)">{{busy===e.event_id?'Saving…':e.registered?'Withdraw':'Register'}}</button></div></div></template></div></div></template>
